function update(dt) {
    if (phase !== 'playing') return;
    // Rotation
    const turn = (keys.has('ArrowRight') || keys.has('d') || keys.has('D') ? 1 : 0) -
                 (keys.has('ArrowLeft')  || keys.has('a') || keys.has('A') ? 1 : 0);
    const TURN_SPEED = Math.PI * 2; // rad per second
    player.angle += turn * TURN_SPEED * dt;
    // Acceleration
    const thrust = keys.has('ArrowUp') || keys.has('w') || keys.has('W');
    if (thrust) {
      player.vx += Math.cos(player.angle) * PLAYER_ACCEL * dt;
      player.vy += Math.sin(player.angle) * PLAYER_ACCEL * dt;
    }
    // Apply friction
    const decay = Math.pow(PLAYER_FRICTION, dt);
    player.vx *= decay;
    player.vy *= decay;
    // Clamp speed
    const speed = Math.hypot(player.vx, player.vy);
    if (speed > PLAYER_MAX_SPEED) {
      const scale = PLAYER_MAX_SPEED / speed;
      player.vx *= scale;
      player.vy *= scale;
    }
    // Update position with wrap
    player.x = (player.x + player.vx * dt + W) % W;
    player.y = (player.y + player.vy * dt + H) % H;
    player.visible = true;
    // Hazards motion
    for (const h of hazards) {
      h.x = (h.x + h.vx * dt + W) % W;
      h.y = (h.y + h.vy * dt + H) % H;
    }
  }

  function spawnHazard() {
    // spawn at random edge position
    const edge = Math.floor(Math.random() * 4);
    let x, y, dirAngle;
    if (edge === 0) { x = 0; y = Math.random()*H; dirAngle = 0; }
    else if (edge === 1) { x = W; y = Math.random()*H; dirAngle = Math.PI; }
    else if (edge === 2) { x = Math.random()*W; y = 0; dirAngle = Math.PI/2; }
    else { x = Math.random()*W; y = H; dirAngle = -Math.PI/2; }
    const speed = HAZARD_SPEED_MIN + Math.random()*(HAZARD_SPEED_MAX-HAZARD_SPEED_MIN);
    const vx = Math.cos(dirAngle)*speed;
    const vy = Math.sin(dirAngle)*speed;
    // ensure safe radius from player start (center)
    if (Math.hypot(x - W/2, y - H/2) < SAFE_RADIUS_AT_SPAWN) return; // skip this spawn
    hazards.push({x, y, vx, vy, r: HAZARD_RADIUS});
  }

